function speedClient(C, pvp) {
  let on = false, lastG = null, lastCo = null, shown = null, btn = null;
  let cur = { ms: 0, id: '' };   // 這場（最近一次開局登記）的計數器
  const runs = new Map();        // run id → 計數器
  const mon = { t0: 0, ticks: -1, frames: 0, bad: 0, last: null };
  // localStorage：{ run id: [毫秒, 時間] }（重新整理後接得上）
  try { const o = JSON.parse(localStorage.getItem(C.store) || '{}'); for (const [k, v] of Object.entries(o || {})) if (Array.isArray(v) && Date.now() - v[1] < 864e5) runs.set(k, { ms: +v[0] || 0, id: k }); } catch (e) {}
  let savedAt = 0;
  const persist = force => {
    const now = Date.now(); if (!force && now - savedAt < 5000) return; savedAt = now;
    try { const o = {}; for (const [k, a] of [...runs].slice(-C.keep)) o[k] = [Math.round(a.ms), now]; localStorage.setItem(C.store, JSON.stringify(o)); } catch (e) {}
  };
  const allowed = (g, co) => {
    try { return !co && !g.coop && !g.endless && !g.isStory && !pvp() && g.state !== 'over'; } catch (e) { return false; }
  };
  function mount() {
    if (btn) return btn;
    const box = document.getElementById('timer-box'); if (!box) return null;
    if (!document.getElementById('spd-css')) { const st = document.createElement('style'); st.id = 'spd-css'; st.textContent = C.css; document.head.appendChild(st); }
    btn = document.createElement('span'); btn.id = 'spd-btn'; btn.className = 'chip'; btn.setAttribute('role', 'button'); btn.tabIndex = -1; btn.style.display = 'none';
    btn.title = C.txt.title; btn.setAttribute('aria-label', C.txt.title);
    btn.onpointerdown = e => e.stopPropagation();
    btn.onclick = e => { e.stopPropagation(); toggle(); };
    box.appendChild(btn); paint();
    return btn;
  }
  function paint() { if (!btn) return; btn.textContent = on ? '2x' : '1x'; btn.classList.toggle('on', on); btn.setAttribute('aria-pressed', on ? 'true' : 'false'); }
  function show(v) { if (shown === v && btn) return; if (!mount()) return; shown = v; btn.style.display = v ? '' : 'none'; }
  const monReset = () => { mon.ticks = -1; mon.frames = 0; };
  function set(v, msg) {
    on = !!v; mon.bad = 0; monReset(); paint();
    if (msg && lastG) try { lastG.events.onAnnounce(msg); } catch (e) {}
    persist(true);
  }
  function toggle() { if (!lastG || !allowed(lastG, lastCo)) return; set(!on); }   // 不跳公告（按鈕變色就是回饋）
  // 實際遊戲速度／fps（只在 2 倍速、遊戲進行中量）
  //   真實時間用 performance.now()：Pixi ticker 的 deltaMS 最多 100ms（minFPS 10），低於 10 fps 時 deltaMS 會少算 → 不能拿它量。
  function monitor(g) {
    const now = performance.now();
    if (mon.ticks < 0) { mon.ticks = g.ticks; mon.t0 = now; mon.frames = 0; return; }
    mon.frames++;
    const real = now - mon.t0;
    if (real < C.monWin) return;
    const speed = (g.ticks - mon.ticks) * C.step * 1000 / real, fps = mon.frames * 1000 / real;
    mon.last = { speed: +speed.toFixed(2), fps: +fps.toFixed(1) };
    mon.ticks = g.ticks; mon.t0 = now; mon.frames = 0;
    if (speed < C.minSpeed || fps < C.minFps) { if (++mon.bad >= C.monBad) set(false, C.txt.slow); } else mon.bad = 0;
  }
  window.addEventListener('keydown', e => {
    const t = e.target, tn = t && t.tagName;
    if (tn === 'INPUT' || tn === 'TEXTAREA' || (t && t.isContentEditable) || e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
    if ((e.key || '').toLowerCase() === C.key) toggle();
  });
  const api = {
    // 每幀：g＝遊戲、co＝組隊連線、d＝這幀真實毫秒、b＝原本的倍率（塔加速）。回傳要用的倍率
    k(g, co, d, b) {
      if (g !== lastG) { lastG = g; if (on) { on = false; paint(); } mon.bad = 0; monReset(); }   // 新的一場 → 1x
      lastCo = co;
      if (b !== 1 || !allowed(g, co)) { show(false); if (on) { on = false; paint(); } g.roSpd = 1; return b; }
      show(true);
      if (!on) { g.roSpd = 1; return 1; }
      if (g.state === 'playing') { cur.ms += d; monitor(g); persist(false); } else monReset();
      g.roSpd = 2; return 2;
    },
    reg() { cur = { ms: 0, id: '' }; return cur; },
    bind(u, a) {
      const rid = u && typeof u.run === 'string' ? u.run : ''; if (!rid || !a) return;
      const old = runs.get(rid); if (old && old !== a) a.ms += old.ms;   // 重送登記回同一個 run id
      a.id = rid; runs.delete(rid); runs.set(rid, a);
      while (runs.size > C.keep) runs.delete(runs.keys().next().value);
      persist(true);
    },
    claim(rid) {
      if (!rid) return {};
      let a = runs.get(String(rid));
      if (!cur.id && cur.ms > 0) {   // 這場沒綁到 run id（重新整理後繼續中斷的場次：開局登記沒重送）→ 算進要認領的這場
        if (a) a.ms += cur.ms; else { a = cur; runs.set(String(rid), a); }
        a.id = String(rid); cur = a; persist(true);
      }
      return a && a.ms > 0 ? { x2: Math.round(a.ms) } : {};
    },
    state: () => ({ on, shown, cur: Math.round(cur.ms), runs: Object.fromEntries([...runs].map(([k, a]) => [k, Math.round(a.ms)])), mon: mon.last, bad: mon.bad }),
    set: v => set(v),
  };
  window.__RO_SPD = api;   // 除錯／測試用
  return api;
}
